      "keystrokes": "cat > solution.py << 'PY'
import sys

def can_make_pal(s: str) -> bool:
    i, j = 0, len(s) - 1
    while i < j and s[i] == s[j]:
        i += 1
        j -= 1
    # If we exhausted the string, it's already a palindrome
    if i >= j:
        return True
    # Helper: check if s[l..r] is palindrome
    def is_pal_sub(l: int, r: int) -> bool:
        while l < r:
            if s[l] != s[r]:
                return False
            l += 1
            r -= 1
        return True
    # Try skipping left character at i or skipping right character at j
    return is_pal_sub(i + 1, j) or is_pal_sub(i, j - 1)


def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    t_line = data[0].strip()
    t = int(t_line) if t_line else 0
    out = []
    idx = 1
    for _ in range(t):
        s = data[idx].strip() if idx < len(data) else ""
        idx += 1
        out.append("YES" if can_make_pal(s) else "NO")
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
