# coding: utf-8
import sys
from collections import deque

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it)); m = int(next(it)); k = int(next(it))
    edges = [None]*(m+1)
    adj = [[] for _ in range(n)]
    for i in range(1, m+1):
        a = int(next(it)) - 1
        b = int(next(it)) - 1
        edges[i] = (a,b)
        adj[a].append((b,i))
        adj[b].append((a,i))
    deg = [0]*n
    for v in range(n):
        deg[v] = len(adj[v])
    alive = [True]*n
    removed = [False]*(m+1)
    q = deque()
    for v in range(n):
        if deg[v] < k:
            q.append(v)
    alive_count = n
    while q:
        v = q.popleft()
        if not alive[v]:
            continue
        alive[v] = False
        alive_count -= 1
        for (u, ei) in adj[v]:
            if removed[ei]:
                continue
            if alive[u]:
                deg[u] -= 1
                if deg[u] < k:
                    q.append(u)
    ans = [0]*(m+1)
    for i in range(m, 0, -1):
        ans[i] = alive_count
        if removed[i]:
            continue
        removed[i] = True
        a,b = edges[i]
        if alive[a] and alive[b]:
            deg[a] -= 1
            deg[b] -= 1
            if deg[a] < k:
                q.append(a)
            if deg[b] < k:
                q.append(b)
        while q:
            v = q.popleft()
            if not alive[v]:
                continue
            alive[v] = False
            alive_count -= 1
            for (u, ei) in adj[v]:
                if removed[ei]:
                    continue
                if alive[u]:
                    deg[u] -= 1
                    if deg[u] < k:
                        q.append(u)
    out_lines = [str(ans[i]) for i in range(1, m+1)]
    print('\n'.join(out_lines))

if __name__ == '__main__':
    solve()
